module top;
  bit woke = 0;
  function bit sample;
    bit value;
    bit armed;
    bit old_value;
    old_value = value;
    if (!armed) begin armed = 1; value = 1; end
    return old_value;
  endfunction
  initial begin
    @(int'(sample.value) + int'(sample())) woke = 1;
  end
  initial begin #2; $display("%0d:%0d", woke, sample.value); $finish; end
endmodule

module top;
  bit [64:0] value = 0;
  bit woke = 0;
  function bit [64:0] sample;
    bit armed = 0;
    bit [64:0] before_value;
    before_value = value;
    if (!armed) begin
      armed = 1;
      value = 1;
    end
    return before_value;
  endfunction
  initial begin
    @(sample()) woke = 1;
  end
  initial begin
    #2;
    $display("%0d:%0d", woke, value);
    $finish;
  end
endmodule

module top;
  int values[$] = '{10, 20};
  bit woke = 0;
  function int sample;
    bit armed = 0;
    int before_value;
    before_value = values[0];
    if (!armed) begin
      armed = 1;
      values[0] = 11;
    end
    return before_value;
  endfunction
  initial begin
    @(sample()) woke = 1;
  end
  initial begin
    #2;
    $display("%0d:%0d", woke, values[0]);
    $finish;
  end
endmodule
